// Cortex Analyst answers arrive nested twice: the SQL API wraps the row, and
// DATA_AGENT_RUN returns a JSON document whose content array holds the text.
const rows = $input.first().json.data || [];
const raw = rows.length ? rows[0][0] : null;
let answer = '';
let parsed = null;
if (raw) {
  try {
    parsed = JSON.parse(raw);
    const texts = (parsed.content || [])
      .filter((block) => block.type === 'text' && block.text)
      .map((block) => block.text.trim())
      .filter((text) => text.length > 0);
    answer = texts.length ? texts[texts.length - 1] : '';
  } catch (error) {
    answer = 'could not parse the agent response: ' + error.message;
  }
}
return [{
  json: {
    run_id: $('Init run').first().json.run_id,
    analyst_answer: answer,
    analyst_ok: answer.length > 0,
  },
}];

// SEARCH_PREVIEW returns a JSON string in a single cell.
const rows = $input.first().json.data || [];
const raw = rows.length ? rows[0][0] : '[]';
const runId = $('Init run').first().json.run_id;
let hits = [];
try {
  const parsed = JSON.parse(raw);
  hits = Array.isArray(parsed) ? parsed : (parsed.results || []);
} catch (error) {
  hits = [];
}
const top = hits.length ? hits[0] : null;
const ownIndex = hits.findIndex((hit) => hit.RUN_ID === runId);
return [{
  json: {
    run_id: runId,
    search_hits: hits.length,
    search_top_title: top ? top.TITLE : null,
    search_top_is_from_this_run: top ? top.RUN_ID === runId : false,
    search_own_chunk_rank: ownIndex >= 0 ? ownIndex + 1 : null,
    search_top_chunk: top ? String(top.CHUNK).slice(0, 400) : null,
    analyst_answer: $('Parse Analyst answer').first().json.analyst_answer,
    analyst_ok: $('Parse Analyst answer').first().json.analyst_ok,
  },
}];

// One readable summary of what was written and what was read back.
const init = $('Init run').first().json;
const search = $('Parse search hit').first().json;
const pgRows = $('Read Postgres directly').all().map((item) => item.json);
const agent = $input.first().json;
const agentText = agent.output || agent.text || JSON.stringify(agent).slice(0, 800);

const lines = [];
lines.push('SNOWFLAKE MEMORY TOUR - run ' + init.run_id);
lines.push('started ' + init.started_at);
lines.push('');
lines.push('1. STANDARD TABLE  MEMORY_DEMO.CORE.SERVICE_TICKETS');
lines.push('   wrote   1 ticket with parameter binding, then updated severity and status');
lines.push('   read    through Cortex Analyst in natural language');
lines.push('   answer  ' + String(search.analyst_answer).replace(/\n+/g, ' ').slice(0, 400));
lines.push('');
lines.push('2. DOCUMENT CORPUS  MEMORY_DEMO.CORE.SERVICE_DOCS + DOC_SEARCH');
lines.push('   wrote   1 runbook chunk tagged with this run id');
lines.push('   read    through Cortex Search, ' + search.search_hits + ' hits');
lines.push('   top hit ' + search.search_top_title +
  (search.search_top_is_from_this_run ? ' (written by this run)' : ' (pre-existing document)'));
lines.push('   the search was filtered on this run id, so a hit proves the chunk was indexed');
lines.push('');
lines.push('3. SNOWFLAKE POSTGRES  demo_events on MEMORY_DEMO_PG');
lines.push('   wrote   1 event, then updated its status');
lines.push('   read    directly with SQL, ' + pgRows.length + ' row(s) for this run');
pgRows.forEach((row) => {
  lines.push('   row     id=' + row.event_id + ' status=' + row.status + ' site=' + row.site);
});
lines.push('');
lines.push('4. AI AGENT, LLM SERVED BY SNOWFLAKE CORTEX THROUGH THE PRIVATE PROXY');
lines.push('   model   claude-sonnet-5 via cortex-proxy-service, no external provider');
lines.push('   tools   ticket_stats (SQL API), search_procedures (Cortex Search), ' +
  'recent_events (Postgres)');
lines.push('   answer  ' + String(agentText).replace(/\n+/g, ' ').slice(0, 1200));

return [{ json: {
  run_id: init.run_id,
  report: lines.join('\n'),
  analyst_ok: search.analyst_ok,
  search_ok: search.search_hits > 0,
  postgres_rows: pgRows.length,
  agent_answer: agentText,
} }];
